import{_ as i,c,o as n,ae as p}from"./chunks/framework.9GttIHxX.js";const d="/notes/assets/mdn-url-all-dark.9FYBQuk7.svg",s="/notes/assets/mdn-url-all-light.Bcl_shso.svg",h="/notes/assets/mdn-url-protocol-dark.9ow-5mQ4.svg",a="/notes/assets/mdn-url-protocol-light.B5nDk4HD.svg",u="/notes/assets/mdn-url-authority-dark.Cjr1vB80.svg",t="/notes/assets/mdn-url-authority-light.DV9pZoQy.svg",m="/notes/assets/mdn-url-path-dark.CBBovIYz.svg",o="/notes/assets/mdn-url-path-light.5UHFFJTL.svg",b="/notes/assets/mdn-url-parameters-dark.Cop8W35W.svg",r="/notes/assets/mdn-url-parameters-light.B9oxDciS.svg",g="/notes/assets/mdn-url-anchor-dark.C-UdlQvT.svg",l="/notes/assets/mdn-url-anchor-light.BZ05LGML.svg",D=JSON.parse('{"title":"🔗 什么是 URL？","description":"","frontmatter":{},"headers":[],"relativePath":"common/url.md","filePath":"common/url.md"}'),_={name:"common/url.md"},k=d,v=s,U=h,q=a,L=u,f=t,R=m,x=o,P=b,y=r,S=g,C=l;function T(W,e,B,z,H,I){return n(),c("div",null,[...e[0]||(e[0]=[p(`<h1 id="🔗-什么是-url" tabindex="-1">🔗 什么是 URL？ <a class="header-anchor" href="#🔗-什么是-url" aria-label="Permalink to &quot;🔗 什么是 URL？&quot;">​</a></h1><blockquote><p>What is a URL?</p></blockquote><h2 id="📰-概述" tabindex="-1">📰 概述 <a class="header-anchor" href="#📰-概述" aria-label="Permalink to &quot;📰 概述&quot;">​</a></h2><blockquote><p>Summary</p></blockquote><p>HTTP 请求的目标称为「资源 🪵」，其性质没有进一步定义；它可以是文档 📄、照片 🏞 或其他任何东西。每个资源都由一个统一资源标识符（Uniform Resource Identifier）标识，该标识符在整个 HTTP 中用于标识资源</p><p>URI 最常见的形式是 URL，也就是众所周知的网址</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://developer.mozilla.org</span></span>
<span class="line"><span>https://developer.mozilla.org/en-US/docs/Learn/</span></span>
<span class="line"><span>https://developer.mozilla.org/en-US/search?q=URL</span></span></code></pre></div><p><strong>URL</strong> 代表统一资源定位器 🧭（Uniform Resource Locator）。URL 只不过是 Web 上给定唯一资源的地址。理论上，每个有效的 URL 都指向一个唯一资源</p><h2 id="🔬-基础-url-剖析" tabindex="-1">🔬 基础：URL 剖析 <a class="header-anchor" href="#🔬-基础-url-剖析" aria-label="Permalink to &quot;🔬 基础：URL 剖析&quot;">​</a></h2><blockquote><p>Basics: anatomy of a URL</p></blockquote><p>URL 由不同的部分组成，有些是必备的，有些则是可选的。下面的 URL 高亮显示了最重要的部分</p><picture><source media="(prefers-color-scheme: dark)" srcset="`+k+'"><source media="(prefers-color-scheme: light)" srcset="'+v+'"><img alt="./url-all" src="'+s+'"></picture><h2 id="🖋-方案" tabindex="-1">🖋 方案 <a class="header-anchor" href="#🖋-方案" aria-label="Permalink to &quot;🖋 方案&quot;">​</a></h2><blockquote><p>Scheme</p></blockquote><picture><source media="(prefers-color-scheme: dark)" srcset="'+U+'"><source media="(prefers-color-scheme: light)" srcset="'+q+'"><img alt="./url-protocol" src="'+a+'"></picture><p>它表示浏览器请求资源必须使用的协议。通常对于网站，协议是 HTTPS 或 HTTP</p><h2 id="👑-权威" tabindex="-1">👑 权威 <a class="header-anchor" href="#👑-权威" aria-label="Permalink to &quot;👑 权威&quot;">​</a></h2><blockquote><p>Authority</p></blockquote><picture><source media="(prefers-color-scheme: dark)" srcset="'+L+'"><source media="(prefers-color-scheme: light)" srcset="'+f+'"><img alt="./url-authority" src="'+t+'"></picture><blockquote><p>权威包括域名和端口</p></blockquote><ul><li>域名指示正在请求哪个 Web 服务器</li><li>端口表示用于访问 Web 服务器上资源的「入口」。标准端口（HTTP 为 80，HTTPS 为 443）通常省略</li></ul><h2 id="🐾-资源路径" tabindex="-1">🐾 资源路径 <a class="header-anchor" href="#🐾-资源路径" aria-label="Permalink to &quot;🐾 资源路径&quot;">​</a></h2><blockquote><p>Path to resource</p></blockquote><picture><source media="(prefers-color-scheme: dark)" srcset="'+R+'"><source media="(prefers-color-scheme: light)" srcset="'+x+'"><img alt="./url-path" src="'+o+'"></picture><p>在 Web 的早期，这样的路径表示 Web 服务器上的物理文件位置。如今，它主要是由 Web 服务器处理的抽象路径</p><h2 id="🎛-参数" tabindex="-1">🎛 参数 <a class="header-anchor" href="#🎛-参数" aria-label="Permalink to &quot;🎛 参数&quot;">​</a></h2><blockquote><p>Parameters</p></blockquote><picture><source media="(prefers-color-scheme: dark)" srcset="'+P+'"><source media="(prefers-color-scheme: light)" srcset="'+y+'"><img alt="./url-parameters" src="'+r+'"></picture><p>参数是用 <code>&amp;</code> 分隔的键/值对列表。Web 服务器可以在返回资源之前使用这些参数来执行额外的操作</p><h2 id="⚓️-锚点" tabindex="-1">⚓️ 锚点 <a class="header-anchor" href="#⚓️-锚点" aria-label="Permalink to &quot;⚓️ 锚点&quot;">​</a></h2><blockquote><p>Anchor</p></blockquote><picture><source media="(prefers-color-scheme: dark)" srcset="'+S+'"><source media="(prefers-color-scheme: light)" srcset="'+C+'"><img alt="./url-anchor" src="'+l+'"></picture><p>代表资源内的一种「书签 🔖」，为浏览器提供了显示位于「书签」位置内容的指示。<code>#</code> 之后的内容不会随请求发送到服务器</p><h2 id="🆚-绝对-url-与相对-url" tabindex="-1">🆚 绝对 URL 与相对 URL <a class="header-anchor" href="#🆚-绝对-url-与相对-url" aria-label="Permalink to &quot;🆚 绝对 URL 与相对 URL&quot;">​</a></h2><blockquote><p>Absolute URLs vs relative URLs</p></blockquote><p>在浏览器的地址栏中，URL 没有任何上下文，因此必须提供完整的 URL</p><p>当在文档中使用 URL 时，因为浏览器已经拥有文档自己的 URL，可以使用此信息来填充文档中 URL 的缺失部分</p><h3 id="绝对-url-示例" tabindex="-1">绝对 URL 示例 <a class="header-anchor" href="#绝对-url-示例" aria-label="Permalink to &quot;绝对 URL 示例&quot;">​</a></h3><blockquote><p>Examples of absolute URLs</p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://developer.mozilla.org/en-US/docs/Learn</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//developer.mozilla.org/en-US/docs/Learn</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/en-US/docs/Learn</span></span></code></pre></div><h3 id="相对-url-示例" tabindex="-1">相对 URL 示例 <a class="header-anchor" href="#相对-url-示例" aria-label="Permalink to &quot;相对 URL 示例&quot;">​</a></h3><blockquote><p>Examples of relative URLs</p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skills/Infrastructure/Understanding_URLs</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>../CSS/display</span></span></code></pre></div><h2 id="💬-语义-url" tabindex="-1">💬 语义 URL <a class="header-anchor" href="#💬-语义-url" aria-label="Permalink to &quot;💬 语义 URL&quot;">​</a></h2><blockquote><p>Semantic URLs</p></blockquote><ul><li>更容易操纵</li><li>为用户阐明了他们在哪里、他们在做什么、他们在 Web 上阅读或与之交互的内容</li><li>一些搜索引擎可以使用这些语义来改进相关页面的分类</li></ul><h2 id="参考文档" tabindex="-1">参考文档 <a class="header-anchor" href="#参考文档" aria-label="Permalink to &quot;参考文档&quot;">​</a></h2><ol><li><a href="https://developer.mozilla.org/en-US/docs/Glossary/URI" target="_blank" rel="noreferrer">URI</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Glossary/URL" target="_blank" rel="noreferrer">URL</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Learn/Common_questions/What_is_a_URL" target="_blank" rel="noreferrer">What is a URL?</a></li></ol>',51)])])}const E=i(_,[["render",T]]);export{D as __pageData,E as default};
